//! `vc-x1 clone`: clone a repo (URL or local path) into a workspace.
//!
//! - Default (no `--por`): dual-repo layout: clones the work repo,
//!   takes the agent-repo's name from the cloned config's
//!   `[remote] agent-repo` (`<source>.agent-session` when the key is
//!   absent),
//!   clones the agent side into the dir the cloned `repos.agent`
//!   names, creates the Claude Code symlink. Both sides must
//!   succeed.
//! - `--por`: single repo into `<target>`. No agent repo, no
//!   symlink.
//!
//! TARGET shapes (all routed through `parse_target`): a URL or a
//! local path (`./X`, `/X`, `~/X`, `.`, `..`). Path-form is
//! symmetric with `git clone /local/bare.git`, useful for fixtures
//! and CI scratch dirs.
//!
//! `clone_one` and `clone_dual` are `pub(crate)` so init's `-3`
//! reshape can reuse them for the "URL exists -> clone" preflight
//! path (per `notes/chores/chores-08.md > init + clone redesign`).

use std::path::Path;

use clap::{Args, ValueHint};
use log::{info, warn};

use crate::context::Context;
use crate::jj;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::por::PorFlag;
use crate::subcommand::SubcommandRunner;
use crate::symlink;
use crate::url::{Target, agent_url, derive_bot_url, derive_name, parse_target};

/// CLI args for `vc-x1 clone`.
#[derive(Args, Debug)]
pub struct CloneArgs {
    /// Source to clone: URL or local path.
    ///
    /// - URL: `git@host:owner/name(.git)?`, `https://...(.git)?`
----
        if params.por {
            info!("  1. clone --colocate {source} {name}");
        } else {
            let bot_source = derive_bot_url(&source);
            info!("  1. clone --colocate {source} {name}");
            info!("  2. clone --colocate {bot_source} {name}/<repos.agent>");
            info!(
                "     (the URL's last segment is the cloned [remote] agent-repo, when it has one)"
            );
            info!("  3. Create Claude Code symlink");
        }
        return Ok(());
    }

    if params.por {
        clone_one(&source, &project_dir)?;
        info!("");
        info!("Done! Project cloned to {}", project_dir.display());
        info!("  Work repo: {}", project_dir.display());
    } else {
        clone_dual(&source, &project_dir)?;
    }

    log::debug!("clone: exit");
    Ok(())
}

/// Clone a single repo (`jj git clone --colocate`
/// semantics) and verify bookmark tracking.
///
/// - `source` is the clone source (URL or local path, a relative
///   path resolving against the process cwd).
/// - `target_dir` is the destination working repo location.
///
/// The facade's clone does git clone + jj init + automatic
/// bookmark tracking in one step (unlike colocate-after-bare-git-clone,
/// which needs explicit `jj bookmark track`). The `verify_tracking`
/// call asserts the post-clone state matches expectations.
pub(crate) fn clone_one(source: &str, target_dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
    info!("Cloning {source} -> {}...", target_dir.display());
    jj::git_clone_colocated(source, target_dir)?;
    crate::common::verify_tracking(target_dir, "main")?;
    Ok(())
}

/// Orchestrate a dual-repo clone: work via `clone_one`, bot via
/// `clone_one` (no graceful skip: both sides required by the
/// default dual shape, and users who want work-only pass `--por`),
/// then create the Claude Code symlink.
pub(crate) fn clone_dual(
    work_source: &str,
    target_dir: &Path,
) -> Result<(), Box<dyn std::error::Error>> {
    clone_one(work_source, target_dir)?;
    // The local bot dir name comes from the *cloned* work repo's
    // config (`repos.agent`), so a workspace that chose a
    // non-`.claude` dir round-trips through clone. A legacy-schema
    // config (which the resolvers reject) is honored here: clone
    // is where an old repo first arrives, so it completes with the
    // legacy-declared bot dir and a warning pointing at the
    // [repos] rewrite. No accepted `repos.agent`, whether the key
    // is absent, misspelled, or the file does not parse, is one
    // error: a dual clone was asked for and the config does not
    // declare one, so the work clone stays as a POR and the error
    // says what to do. Any command run there prints the precise
    // rejection.
    let no_agent = || -> Box<dyn std::error::Error> {
        format!(
            "cloned the work-repo, but its {} [repos].agent is missing, so no agent-repo \
             was cloned.\nAdd it, or rename repos.bot to repos.agent if the config is \
             pre-0.80.0.",
            crate::config_md::VC_CONFIG_MD
        )
        .into()
    };
    // The agent-repo's remote name comes from the same cloned
    // config's `[remote] agent-repo`, so the derivation waits for the work
    // clone too. It is
    // read only where `configured_bot_dir` accepted the config: the
    // legacy branch got here because the `[repos]` config was
    // rejected, and a rejected config has no key to read.
    let (bot_dir, agent_repo) = match crate::common::configured_bot_dir(target_dir) {
        Ok(Some(p)) => (p, crate::common::configured_agent_repo(target_dir)?),
        Ok(None) => return Err(no_agent()),
        Err(_) => match crate::legacy_vc_config::configured_bot_dir(target_dir) {
            Some(p) => {
                warn!(
                    "cloned work repo uses a legacy .vc-config.toml schema; \
                     continuing with its declared bot dir '{}'. Update both \
                     sides' configs to the [repos] registry: any vc-x1 \
                     command in the workspace prints the exact rewrite",
                    p.display()
                );
                (p, None)
            }
            None => return Err(no_agent()),
        },
    };
    let bot_source = agent_url(work_source, agent_repo.as_deref());
    // A relative local-path TARGET resolves against the process
    // cwd for both sides (the facade absolutizes it before it is
    // stored), which is what the old spawn's explicit `parent_dir`
    // cwd guaranteed (bugs.md #2).
    clone_one(&bot_source, &bot_dir)?;
    info!("Creating Claude Code symlink...");
    let sl = symlink::install(target_dir)?;

    info!("");
    info!("Done! Project cloned to {}", target_dir.display());
    info!("  Work repo:    {}", target_dir.display());
    info!("  Bot repo:     {}", bot_dir.display());
    info!(
        "  Symlink:      {} -> {}",
        sl.symlink_path.display(),
        sl.abs_target.display()
    );

    Ok(())
}

